    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) {
            continue;
        }
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) {
            continue;
        }
        used[i] = true;
        current.add(nums[i]);
        generatePermutations(nums, used, result, current);
        used[i] = false;
        current.remove(current.size() - 1);
    }
}
