public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 1) return cost[0];
    if (n == 2) return Math.min(cost[0], cost[1]);
    int prev = cost[0], curr = Math.min(cost[0], cost[1]);
    for (int i = 2; i < n; i++) {
        int next = Math.min(prev + cost[i], curr + cost[i - 1]);
        prev = curr;
        curr = next;
    }
    return curr;
}
