    for (int i = 2; i < cost.length; i++) {
        int currentCost = cost[i];
        minCost = Math.min(minCost, prevPrev + currentCost);
        int tmp = prevPrev;
        prevPrev = prev;
        prev = currentCost + Math.min(prev, tmp);
    }
    return minCost;
}
