package com.example.graphtraversalorder;

import java.util.HashSet;
import java.util.Queue;

public class GraphTraversalOrder {
    private final String order;
    private int visited;

    public GraphTraversalOrder(String order) {
        this.order = order;
    }

    public void traversalOrder(Graph graph) {
        visited = 0;
        if (order.equals("depth-first")) {
            dfs(graph.getStart());
        } else if (order.equals("breadth-first")) {
            bfs(new HashSet<>());
        } else {
            throw new UnsupportedOperationException("Invalid traversal order");
        }
        System.out.println("Number of nodes visited: " + visited);
