    private void dfs(Node node) {
        if (visited == -1) return;
        visited++;
        for (Node neighbor : node.getNeighbors()) {
            dfs(neighbor);
        }
    }

    private void bfs(Queue<Node> queue) {
        if (queue.isEmpty()) return;
        visited++;
        Node node = queue.poll();
        for (Node neighbor : node.getNeighbors()) {
            queue.add(neighbor);
        }
        bfs(queue);
    }

    public static void main(String[] args) {
