public static int squarePermutations(int[] A) {
    int n = A.length;
    int[][] dp = new int[n][n];
    for (int i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    for (int k = 0; k < n - 1; k++) {
        for (int i = 0; i < n - k - 1; i++) {
            int j = i + k + 1;
            for (int m = i; m <= j; m++) {
                int x = (int) Math.sqrt(A[i] + A[m]);
                if (x * x == A[i] + A[m]) {
                    dp[i][j] += dp[i][m] * dp[m + 1][j];
                }
            }
        }
    }
    return dp[0][n - 1];
}
