public static boolean checkBoomerang(int[] start, int[] middle, int[] end){
    int dx1 = start[0]-middle[0];
    int dy1 = start[1]-middle[1];
    int dx2 = middle[0]-end[0];
    int dy2 = middle[1]-end[1];
    int crossproduct = dx1*dy2-dx2*dy1;
    if(crossproduct == 0){
        return false;
    }
    int dxsq = (start[0]-middle[0])*(middle[0]-start[0]);
    int dysq = (start[1]-middle[1])*(middle[1]-start[1]);
    int dxmsq = (middle[0]-start[0])*(start[0]-end[0]);
    int dymsq = (middle[1]-start[1])*(start[1]-end[1]);
    int cxsq = dxsq - dxmsq;
    int cysq = dysq - dymsq;
    if(cxsq + cysq == 0){
        return false;
    }
    int dax = start[0]-end[0];
    int day = start[1]-end[1];
    int c = dx1*day-dy1*dax;
    int sq1 = cxsq*day-cysq*dax;
    int sq2 = dx2*cysq-dy2*cxsq;
    if(sq1*sq2 == 0){
        return false;
    }
    return (c*sq1*sq2)/(cxsq*day-cysq*dax) >= 0;
}
